insert into public.problems (id,slug,title,summary,description,affected_groups,evidence,severity,status,research_status,origin,reviewed_by_human,last_researched_at,created_by) values
('30000000-0000-4000-8000-000000000001','restaurant-food-waste','Restaurants cannot match daily supply to volatile demand','Independent restaurants discard usable food because demand signals arrive after purchasing and prep decisions.','Small food businesses operate on thin margins and fragmented data. Weather, events and delivery-platform demand can shift the day, but planning is still based on memory and static averages.',array['Independent restaurant owners','Kitchen teams','Community food organizations'],array['Perishable stock is ordered before demand is visible','Donation coordination begins too late in the day'], 'high','draft','verified','human',true,'2026-08-20T08:00:00Z','10000000-0000-4000-8000-000000000001'),
('30000000-0000-4000-8000-000000000002','last-mile-clinic-delays','Community clinics lose hours to unpredictable medicine deliveries','Small clinics cannot see consolidated courier and inventory state.','Medicine orders cross multiple distributors and couriers, leaving clinic staff to reconcile updates by phone. The uncertainty creates patient delays and emergency purchasing.',array['Community clinics','Patients','Pharmacy coordinators'],array['Delivery status is fragmented across vendors','Staff manually call distributors for updates'],'critical','draft','needs_review','human',true,null,'10000000-0000-4000-8000-000000000002'),
('30000000-0000-4000-8000-000000000003','small-farm-cold-chain','Small farms lack affordable cold-chain coordination','Produce quality declines while farmers wait for transport and shared storage.','Cold rooms and refrigerated vehicles exist, but capacity is hard to discover and reserve in small increments.',array['Smallholder farmers','Produce cooperatives'],array['Capacity is underused while nearby produce spoils'],'high','draft','verified','imported',true,'2026-08-18T08:00:00Z','10000000-0000-4000-8000-000000000002'),
('30000000-0000-4000-8000-000000000004','tenant-repair-visibility','Tenants cannot track shared-building repair accountability','Repair reports disappear between property managers, vendors and residents.','Residents repeatedly report the same issue because ownership, evidence and completion criteria are not visible.',array['Tenants','Property managers','Maintenance vendors'],array['Duplicate reports hide the true incident history'],'medium','draft','unresearched','human',true,null,'10000000-0000-4000-8000-000000000003'),
('30000000-0000-4000-8000-000000000005','freelancer-payment-proof','Freelancers lack portable proof of reliable client payment','Payment risk is learned privately and too late.','Independent workers cannot carry verifiable payment-timing evidence between communities without exposing contract details.',array['Freelancers','Small agencies'],array['Private warnings do not compound into market evidence'],'medium','draft','needs_review','ai_assisted',true,null,'10000000-0000-4000-8000-000000000003');
