insert into public.ideas (id,slug,title,summary,thesis,solution,target_users,status,research_status,origin,reviewed_by_human,last_researched_at,created_by) values
('40000000-0000-4000-8000-000000000001','demand-pulse-for-kitchens','Demand Pulse for independent kitchens','A calm planning signal assembled from the context restaurants already have.','The useful product is not a perfect forecast. It is an early, explainable range that helps a kitchen change prep quantities before ingredients become sunk cost.','Combine booking pace, weather, local events and the restaurant’s own sales history into a morning demand band. Show what changed and let the operator accept or override each recommendation.',array['Owner-operated restaurants','Kitchen managers'],'draft','verified','human',true,'2026-08-21T08:00:00Z','10000000-0000-4000-8000-000000000001'),
('40000000-0000-4000-8000-000000000002','surplus-window-exchange','Surplus Window Exchange','Coordinate predictable pickup windows before service ends.','Donation works when receivers can plan, not when leftovers are announced at closing time.','Restaurants declare likely surplus bands early; nearby community kitchens reserve collection windows with final quantity confirmed later.',array['Restaurants','Community kitchens'],'draft','needs_review','human',true,null,'10000000-0000-4000-8000-000000000001'),
('40000000-0000-4000-8000-000000000003','clinic-delivery-ledger','Clinic Delivery Ledger','One shared state for multi-vendor medicine delivery.','A small clinic needs exception visibility more than another procurement suite.','Normalize courier and distributor status into a clinic-first timeline with ownership for every exception.',array['Clinic coordinators'],'draft','unresearched','human',true,null,'10000000-0000-4000-8000-000000000002'),
('40000000-0000-4000-8000-000000000004','medicine-route-pooling','Medicine Route Pooling','Pool low-volume clinic deliveries by service window.','Clinics can trade speed they do not need for route reliability they do.','Create fixed regional delivery windows across participating distributors and clinics.',array['Clinics','Medicine distributors'],'draft','needs_review','ai_assisted',true,null,'10000000-0000-4000-8000-000000000002'),
('40000000-0000-4000-8000-000000000005','cold-slot-market','Cold Slot Market','Reserve unused cold capacity in crate-sized units.','Existing capacity becomes useful when discovery, handling rules and arrival windows are standardized.','A cooperative inventory of cold rooms and refrigerated routes with small, timed reservations.',array['Farmer cooperatives','Cold-room operators'],'draft','verified','imported',true,'2026-08-18T08:00:00Z','10000000-0000-4000-8000-000000000002'),
('40000000-0000-4000-8000-000000000006','harvest-handoff','Harvest Handoff','Make produce readiness visible to transport coordinators.','Transport misses are often information misses.','A low-bandwidth readiness board that groups harvest lots by destination and temperature need.',array['Smallholder farmers','Transport coordinators'],'draft','unresearched','human',true,null,'10000000-0000-4000-8000-000000000003'),
('40000000-0000-4000-8000-000000000007','repair-evidence-thread','Repair Evidence Thread','A resident-visible incident record with explicit completion evidence.','Trust improves when every handoff and definition of done is visible.','Merge duplicate reports into one incident, assign an accountable owner and require before/after evidence to close.',array['Tenants','Property managers'],'draft','verified','human',true,'2026-08-11T08:00:00Z','10000000-0000-4000-8000-000000000003'),
('40000000-0000-4000-8000-000000000008','building-maintenance-map','Building Maintenance Map','Reveal recurring failures across shared building systems.','Repair histories should inform preventive maintenance.','Map incidents to building assets and surface repeat patterns without exposing resident identity.',array['Building operators'],'draft','unresearched','human',true,null,'10000000-0000-4000-8000-000000000003'),
('40000000-0000-4000-8000-000000000009','payment-timing-attestations','Payment Timing Attestations','Private contracts, portable timing evidence.','Workers need aggregate client reliability without publishing invoices.','Create consented attestations that disclose timing bands and dispute state, never contract value.',array['Freelancers','Small agencies'],'draft','needs_review','human',true,null,'10000000-0000-4000-8000-000000000003'),
('40000000-0000-4000-8000-000000000010','milestone-expectation-card','Milestone Expectation Card','Make acceptance and payment clocks explicit before work starts.','Many disputes begin with mismatched operational expectations rather than bad intent.','A portable pre-contract card defining evidence, review window and payment timing.',array['Freelancers','Clients'],'draft','unresearched','human',true,null,'10000000-0000-4000-8000-000000000003');
