begin;






update public.problems set status='published';
update public.ideas set status='published';




select ('70000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid, case when n <= 5 then 'problem' else 'idea' end,
case when n <= 5 then ('30000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid else ('40000000-0000-4000-8000-' || lpad((n-5)::text,12,'0'))::uuid end,
case when n <= 5 then 'What evidence would change this problem framing?' else 'What is the smallest falsifiable pilot?' end,
case when n <= 5 then 'Share a field observation or source that sharpens the boundary of this problem.' else 'Describe the first test, the decision it unlocks, and what failure would teach us.' end,
('10000000-0000-4000-8000-' || lpad(((n-1)%3+1)::text,12,'0'))::uuid from generate_series(1,10) n;

commit;
